'use client';
import {useEffect,useId,useRef,useState,type ReactNode} from 'react';
import {AnimatePresence,motion,useReducedMotion} from 'motion/react';
import './block-data-table12.css';
export interface FacetedOrder {id:string;order:string;item:string;quantity:number;customer:string;orderStatus:string;paymentStatus:string;paymentMethod:string}
export interface OrderTableFilters {query:string;orderStatus:string[];paymentStatus:string[]}
export interface BlockDataTable12Props {rows:FacetedOrder[];title?:string;description?:ReactNode;onFiltersChange?:(filters:OrderTableFilters)=>void;onOrderSelect?:(order:FacetedOrder)=>void;className?:string}
type IconName='plus'|'view'|'sort'|'down'|'up'|'left'|'right'|'first'|'last'|'search'|'check'|'fulfilled'|'pickup'|'clock'|'paid'|'pending'|'refunded'|'partial';
function Icon({name}:{name:IconName}){let shape:ReactNode;switch(name){case'plus':shape=<><circle cx="12" cy="12" r="9"/><path d="M12 8v8M8 12h8"/></>;break;case'view':shape=<><path d="M4 6h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="white"/><circle cx="16" cy="18" r="2" fill="white"/></>;break;case'search':shape=<><circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/></>;break;case'check':shape=<path d="m4 12 5 5L20 6"/>;break;case'sort':shape=<path d="m8 8 4-4 4 4m-8 8 4 4 4-4"/>;break;case'down':shape=<path d="m6 9 6 6 6-6"/>;break;case'up':shape=<path d="m6 15 6-6 6 6"/>;break;case'left':case'first':shape=<><path d="m14 6-6 6 6 6"/>{name==='first'&&<path d="m20 6-6 6 6 6"/>}</>;break;case'right':case'last':shape=<><path d="m10 6 6 6-6 6"/>{name==='last'&&<path d="m4 6 6 6-6 6"/>}</>;break;case'fulfilled':shape=<><path d="M22 11.1V12a10 10 0 1 1-5.93-9.14"/><path d="m9 11 3 3L22 4"/></>;break;case'pickup':shape=<><path d="m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9M7 5.5l9 5V16"/></>;break;case'paid':shape=<path d="m2 12 4 4L17 5M8 16l4 4L23 9"/>;break;case'pending':shape=<>{Array.from({length:8},(_,i)=><path key={i} d="M12 2v4" transform={`rotate(${i*45} 12 12)`}/>)}</>;break;case'refunded':shape=<><path d="M3 10a9 9 0 0 1 15-6l3 3M21 2v5h-5M21 14A9 9 0 0 1 6 20l-3-3M3 22v-5h5"/></>;break;case'partial':shape=<><path d="M21 12A9 9 0 1 1 12 3v9zM16 3a9 9 0 0 1 5 5h-5z"/></>;break;default:shape=<><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></>}
return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{shape}</svg>}
const statusIcon=(value:string):IconName=>({'Fulfilled':'fulfilled','Ready for pickup':'pickup','Unfulfilled':'clock','Paid':'paid','Pending':'pending','Refunded':'refunded','Partially refunded':'partial'} as Record<string,IconName>)[value]||'clock';
function Badge({value}:{value:string}){return <span className="dt12-badge" data-tone={['Paid','Fulfilled'].includes(value)?'dark':['Pending','Ready for pickup'].includes(value)?'muted':'outline'}><Icon name={statusIcon(value)}/>{value}</span>}
const columns=[['customer','Customer'],['orderStatus','Order Status'],['paymentStatus','Payment Status'],['paymentMethod','Payment Method']] as const;
export function BlockDataTable12({rows,title='Data Table With Faceted Filters',description='A feature-rich data table with sorting, global filtering, hideable columns, faceted filters and full pagination controls with responsive design.',onFiltersChange,onOrderSelect,className=''}:BlockDataTable12Props){
 const reduced=useReducedMotion();const [filters,setFilters]=useState<OrderTableFilters>({query:'',orderStatus:[],paymentStatus:[]});const[sort,setSort]=useState<{key:'order'|'customer';direction:1|-1}|null>(null);const[hidden,setHidden]=useState<string[]>([]);const[page,setPage]=useState(0);const[size,setSize]=useState(10);const[panel,setPanel]=useState<string|null>(null);const[optionQuery,setOptionQuery]=useState('');const root=useRef<HTMLElement>(null);const lastTrigger=useRef<HTMLButtonElement|null>(null);const panelId=useId();
 const close=()=>{setPanel(null);lastTrigger.current?.focus({preventScroll:true})};
 useEffect(()=>{if(!panel)return;const dismiss=(e:PointerEvent)=>{if(!(e.target as Element).closest('.dt12-pop-anchor'))setPanel(null)};const escape=(e:KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();setPanel(null);lastTrigger.current?.focus({preventScroll:true})}};document.addEventListener('pointerdown',dismiss);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('pointerdown',dismiss);document.removeEventListener('keydown',escape)}},[panel]);
 const update=(next:OrderTableFilters)=>{setFilters(next);setPage(0);onFiltersChange?.(next)};
 const matches=(r:FacetedOrder,exclude?:string)=>`${r.order} ${r.item} ${r.customer} ${r.orderStatus} ${r.paymentStatus} ${r.paymentMethod}`.toLowerCase().includes(filters.query.toLowerCase())&&(['orderStatus','paymentStatus'] as const).every(key=>key===exclude||!filters[key].length||filters[key].includes(r[key]));
 const filtered=rows.filter(r=>matches(r)).sort((a,b)=>sort?sort.direction*a[sort.key].localeCompare(b[sort.key],undefined,{numeric:true}):0);const pages=Math.ceil(filtered.length/size);const current=Math.min(page,Math.max(0,pages-1));const shown=filtered.slice(current*size,(current+1)*size);
 function toggle(name:string,e:React.MouseEvent<HTMLButtonElement>){lastTrigger.current=e.currentTarget;setPanel(panel===name?null:name);setOptionQuery('')}
 function keyboard(e:React.KeyboardEvent){if(e.key==='Escape'&&panel){e.preventDefault();close()}if(panel&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const nodes=[...root.current!.querySelectorAll<HTMLButtonElement>('.dt12-panel [role=option],.dt12-panel [role=menuitemcheckbox]')];const i=nodes.indexOf(document.activeElement as HTMLButtonElement);nodes[e.key==='Home'?0:e.key==='End'?nodes.length-1:(i+(e.key==='ArrowDown'?1:-1)+nodes.length)%nodes.length]?.focus()}}
 function facet(key:'orderStatus'|'paymentStatus',label:string){const options=key==='orderStatus'?['Fulfilled','Ready for pickup','Unfulfilled']:['Paid','Pending','Refunded','Partially refunded'];const selected=filters[key];return <div className="dt12-pop-anchor"><button className="dt12-facet" aria-expanded={panel===key} aria-controls={panel===key?panelId:undefined} onClick={e=>toggle(key,e)}><Icon name="plus"/>{label}{selected.length>0&&<span className="dt12-selections">{selected.length>2?`${selected.length} selected`:selected.map(s=><small key={s}>{s}</small>)}</span>}</button><AnimatePresence>{panel===key&&<motion.div initial={{opacity:0,y:-8,scale:.95}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:-8,scale:.95}} transition={{duration:reduced?0:.1}} className="dt12-panel dt12-filter" id={panelId} role="dialog" aria-label={label}><label className="dt12-menu-search"><Icon name="search"/><input autoFocus role="combobox" aria-label={`Search ${label}`} aria-controls={`${panelId}-options`} aria-expanded="true" placeholder={label} value={optionQuery} onChange={e=>setOptionQuery(e.target.value)}/></label><div id={`${panelId}-options`} role="listbox" aria-label={label} aria-multiselectable="true">{options.filter(s=>s.toLowerCase().includes(optionQuery.toLowerCase())).map((s,i)=><button key={s} type="button" role="option" aria-selected={selected.includes(s)} className={i===0?'dt12-first-option':''} onClick={()=>update({...filters,[key]:selected.includes(s)?selected.filter(v=>v!==s):[...selected,s]})}><span className="dt12-checkbox" data-checked={selected.includes(s)}>{selected.includes(s)&&<Icon name="check"/>}</span><Icon name={statusIcon(s)}/><span>{s}</span><small>{rows.filter(r=>matches(r,key)&&r[key]===s).length}</small></button>)}{!options.some(s=>s.toLowerCase().includes(optionQuery.toLowerCase()))&&<p className="dt12-no-option">No results found.</p>}{selected.length>0&&<button role="option" aria-selected="false" className="dt12-clear" onClick={()=>update({...filters,[key]:[]})}>Clear filters</button>}</div></motion.div>}</AnimatePresence></div>}
 function orderSort(key:'order'|'customer'){setSort(sort?.key!==key?{key,direction:1}:sort.direction===1?{key,direction:-1}:null)}
 return <section ref={root} className={`block-data-table12 ${className}`} data-capture-root onKeyDown={keyboard}><div className="dt12-inner"><h2>{title}</h2><p className="dt12-description">{description}</p><div className="dt12-toolbar"><input className="dt12-search" aria-label="Search orders" placeholder="Search everything..." value={filters.query} onChange={e=>update({...filters,query:e.target.value})}/>{facet('orderStatus','Order Status')}{facet('paymentStatus','Payment Status')}<div className="dt12-pop-anchor dt12-view"><button onClick={e=>toggle('columns',e)} aria-expanded={panel==='columns'}><Icon name="view"/>View{hidden.length>0&&<small>{hidden.length}</small>}</button><AnimatePresence>{panel==='columns'&&<motion.div initial={{opacity:0,y:-8,scale:.95}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:-8,scale:.95}} transition={{duration:reduced?0:.1}} className="dt12-panel" role="menu" aria-label="Toggle columns"><p className="dt12-menu-title">Toggle columns</p>{columns.map(([key,label])=><button key={key} role="menuitemcheckbox" aria-checked={!hidden.includes(key)} onClick={()=>{setHidden(h=>h.includes(key)?h.filter(v=>v!==key):[...h,key]);close()}}><span className="dt12-check-space">{!hidden.includes(key)&&<Icon name="check"/>}</span>{label}</button>)}</motion.div>}</AnimatePresence></div></div><div className="dt12-table-scroll"><table><colgroup><col style={{width:135.75}}/><col style={{width:190.53}}/>{!hidden.includes('customer')&&<col style={{width:130.95}}/>}{!hidden.includes('orderStatus')&&<col style={{width:172.59}}/>}{!hidden.includes('paymentStatus')&&<col style={{width:178.58}}/>}{!hidden.includes('paymentMethod')&&<col style={{width:149.6}}/>}</colgroup><thead><tr><th aria-sort={sort?.key==='order'?(sort.direction===1?'ascending':'descending'):'none'}><button className="dt12-sort" onClick={()=>orderSort('order')}>Order<Icon name={sort?.key==='order'?(sort.direction===1?'up':'down'):'sort'}/></button></th><th>Purchased</th>{!hidden.includes('customer')&&<th aria-sort={sort?.key==='customer'?(sort.direction===1?'ascending':'descending'):'none'}><button className="dt12-sort" onClick={()=>orderSort('customer')}>Customer<Icon name={sort?.key==='customer'?(sort.direction===1?'up':'down'):'sort'}/></button></th>}{!hidden.includes('orderStatus')&&<th>Order Status</th>}{!hidden.includes('paymentStatus')&&<th>Payment Status</th>}{!hidden.includes('paymentMethod')&&<th>Payment Method</th>}</tr></thead><tbody>{shown.map(r=><tr key={r.id} data-row-id={r.id}><td className="dt12-id">{onOrderSelect?<button className="dt12-order-link" onClick={()=>onOrderSelect(r)}>{r.order}</button>:r.order}</td><td className="dt12-purchased"><span className="dt12-purchase-content">{r.item}<span>{r.quantity}</span></span></td>{!hidden.includes('customer')&&<td>{r.customer}</td>}{!hidden.includes('orderStatus')&&<td><Badge value={r.orderStatus}/></td>}{!hidden.includes('paymentStatus')&&<td><Badge value={r.paymentStatus}/></td>}{!hidden.includes('paymentMethod')&&<td className="dt12-id">{r.paymentMethod}</td>}</tr>)}{!shown.length&&<tr><td className="dt12-empty" colSpan={6-hidden.length}>No results.</td></tr>}</tbody></table></div><footer className="dt12-pagination"><span className="dt12-results">{filtered.length?`Showing ${current*size+1} to ${Math.min((current+1)*size,filtered.length)} of ${filtered.length} rows`:'No results'}</span><div className="dt12-page-size"><span>Rows per page</span><div className="dt12-pop-anchor"><button role="combobox" aria-label="Rows per page" aria-expanded={panel==='size'} onClick={e=>toggle('size',e)}>{size}<Icon name="down"/></button><AnimatePresence>{panel==='size'&&<motion.div initial={{opacity:0,scale:.95}} animate={{opacity:1,scale:1}} exit={{opacity:0,scale:.95}} transition={{duration:reduced?0:.1}} className="dt12-panel dt12-size-options" role="listbox" aria-label="Rows per page">{[10,20].map(n=><button role="option" aria-selected={size===n} key={n} onClick={()=>{setSize(n);setPage(0);close()}}>{n}{size===n&&<Icon name="check"/>}</button>)}</motion.div>}</AnimatePresence></div></div><span>Page {current+1} of {pages}</span><div className="dt12-page-buttons">{(['first','left','right','last'] as const).map((icon,i)=><button key={icon} aria-label={`Go to ${['first','previous','next','last'][i]} page`} disabled={i<2?current===0:current>=pages-1} onClick={()=>setPage(i===0?0:i===1?current-1:i===2?current+1:pages-1)}><Icon name={icon}/></button>)}</div></footer></div></section>;
}
export default BlockDataTable12;
